    /** Expand a compressed run list into versions, oldest-first. */
    fun expand(key: String): List<String> =
        MAP[key]?.let { expandRuns(it) } ?: emptyList()

    private val runRe = Regex("""(.*)(\d+)-(\d+)""")
    private fun expandRuns(s: String): List<String> =
        if (s.isEmpty()) emptyList() else s.split(',').flatMap { seg ->
            val m = runRe.find(seg.trim())
            if (m != null) {
                val (base, lo, hi) = m.destructured
                (lo.toInt()..hi.toInt()).map { base + it }
            } else listOf(seg.trim())
        }.reversed()  // stored newest-first, expand returns oldest
}
